/**
 * Group Validation and Error Handling
 * 
 * Validações robustas para operações de grupo em alto volume,
 * prevenindo falhas e melhorando estabilidade.
 * 
 * @module group-validation
 * @version 1.0.0
 */

import { isJidGroup } from '../WABinary/index.js';

/**
 * Validador de grupos
 */
export class GroupValidator {
    constructor(logger) {
        this.logger = logger;
    }
    
    /**
     * Valida JID de grupo
     * 
     * @param {string} jid - JID para validar
     * @returns {object} Resultado da validação
     */
    validateGroupJid(jid) {
        if (!jid) {
            return {
                valid: false,
                error: 'JID is null or undefined'
            };
        }
        
        if (typeof jid !== 'string') {
            return {
                valid: false,
                error: `JID must be string, got ${typeof jid}`
            };
        }
        
        if (!isJidGroup(jid)) {
            return {
                valid: false,
                error: 'JID is not a group'
            };
        }
        
        return { valid: true };
    }
    
    /**
     * Valida mensagem antes de enviar
     * 
     * @param {object} message - Mensagem para validar
     * @returns {object} Resultado da validação
     */
    validateMessage(message) {
        if (!message) {
            return {
                valid: false,
                error: 'Message is null or undefined'
            };
        }
        
        if (typeof message !== 'object') {
            return {
                valid: false,
                error: `Message must be object, got ${typeof message}`
            };
        }
        
        // Verifica se tem pelo menos um tipo de conteúdo
        const hasContent = !!(
            message.text ||
            message.image ||
            message.video ||
            message.audio ||
            message.document ||
            message.sticker ||
            message.location ||
            message.contact ||
            message.poll
        );
        
        if (!hasContent) {
            return {
                valid: false,
                error: 'Message has no content'
            };
        }
        
        return { valid: true };
    }
    
    /**
     * Valida tamanho de grupo
     * 
     * @param {number} participantCount - Número de participantes
     * @returns {object} Resultado da validação
     */
    validateGroupSize(participantCount) {
        if (typeof participantCount !== 'number') {
            return {
                valid: false,
                error: `Participant count must be number, got ${typeof participantCount}`
            };
        }
        
        if (participantCount < 0) {
            return {
                valid: false,
                error: 'Participant count cannot be negative'
            };
        }
        
        if (participantCount > 1024) {
            this.logger.warn({ participantCount }, 'group size exceeds WhatsApp limit');
            return {
                valid: true,
                warning: 'Group size exceeds official WhatsApp limit (1024)'
            };
        }
        
        return { valid: true };
    }
}

/**
 * Tratador de erros de grupo
 */
export class GroupErrorHandler {
    constructor(logger) {
        this.logger = logger;
        this.errorCounts = new Map();
        this.lastErrors = new Map();
    }
    
    /**
     * Trata erro de envio de mensagem
     * 
     * @param {Error} error - Erro ocorrido
     * @param {string} groupJid - JID do grupo
     * @param {object} context - Contexto adicional
     * @returns {object} Ação recomendada
     */
    handleSendError(error, groupJid, context = {}) {
        const errorType = this.classifyError(error);
        
        // Registra erro
        this.recordError(groupJid, errorType);
        
        this.logger.error({
            error: error.message,
            errorType,
            groupJid,
            context
        }, 'group message send error');
        
        // Determina ação
        switch (errorType) {
            case 'RATE_LIMIT':
                return {
                    action: 'RETRY_WITH_BACKOFF',
                    delay: this.calculateBackoff(groupJid),
                    message: 'Rate limit exceeded, retry with backoff'
                };
                
            case 'SESSION_ERROR':
                return {
                    action: 'RECREATE_SESSION',
                    message: 'Session error, recreate session'
                };
                
            case 'GROUP_NOT_FOUND':
                return {
                    action: 'SKIP',
                    message: 'Group not found or bot removed'
                };
                
            case 'NETWORK_ERROR':
                return {
                    action: 'RETRY_IMMEDIATE',
                    maxRetries: 3,
                    message: 'Network error, retry immediately'
                };
                
            case 'ENCRYPTION_ERROR':
                return {
                    action: 'RECREATE_SESSION',
                    message: 'Encryption error, recreate session'
                };
                
            default:
                return {
                    action: 'RETRY_WITH_BACKOFF',
                    delay: 5000,
                    message: 'Unknown error, retry with backoff'
                };
        }
    }
    
    /**
     * Classifica tipo de erro
     * 
     * @param {Error} error - Erro para classificar
     * @returns {string} Tipo do erro
     */
    classifyError(error) {
        const message = error.message?.toLowerCase() || '';
        
        if (message.includes('rate') || message.includes('429')) {
            return 'RATE_LIMIT';
        }
        
        if (message.includes('session') || message.includes('401')) {
            return 'SESSION_ERROR';
        }
        
        if (message.includes('not found') || message.includes('404')) {
            return 'GROUP_NOT_FOUND';
        }
        
        if (message.includes('network') || message.includes('timeout') || message.includes('econnrefused')) {
            return 'NETWORK_ERROR';
        }
        
        if (message.includes('encrypt') || message.includes('decrypt') || message.includes('cipher')) {
            return 'ENCRYPTION_ERROR';
        }
        
        return 'UNKNOWN';
    }
    
    /**
     * Registra erro
     * 
     * @param {string} groupJid - JID do grupo
     * @param {string} errorType - Tipo do erro
     */
    recordError(groupJid, errorType) {
        const count = this.errorCounts.get(groupJid) || 0;
        this.errorCounts.set(groupJid, count + 1);
        
        this.lastErrors.set(groupJid, {
            type: errorType,
            timestamp: Date.now()
        });
    }
    
    /**
     * Calcula backoff exponencial
     * 
     * @param {string} groupJid - JID do grupo
     * @returns {number} Delay em ms
     */
    calculateBackoff(groupJid) {
        const errorCount = this.errorCounts.get(groupJid) || 0;
        // Backoff exponencial: 1s, 2s, 4s, 8s, max 30s
        const delay = Math.min(1000 * Math.pow(2, errorCount), 30000);
        
        // Adiciona jitter (±20%) para evitar thundering herd
        const jitter = delay * (0.8 + Math.random() * 0.4);
        
        return Math.round(jitter);
    }
    
    /**
     * Limpa contadores de erro antigos
     * 
     * @param {number} maxAge - Idade máxima em ms (padrão: 1 hora)
     */
    cleanup(maxAge = 60 * 60 * 1000) {
        const now = Date.now();
        
        for (const [groupJid, lastError] of this.lastErrors.entries()) {
            if (now - lastError.timestamp > maxAge) {
                this.errorCounts.delete(groupJid);
                this.lastErrors.delete(groupJid);
            }
        }
    }
    
    /**
     * Obtém estatísticas de erros
     * 
     * @returns {object} Estatísticas
     */
    getStats() {
        const stats = {
            totalGroups: this.errorCounts.size,
            errorsByType: {},
            topErrorGroups: []
        };
        
        // Conta erros por tipo
        for (const lastError of this.lastErrors.values()) {
            const type = lastError.type;
            stats.errorsByType[type] = (stats.errorsByType[type] || 0) + 1;
        }
        
        // Top grupos com mais erros
        const sorted = Array.from(this.errorCounts.entries())
            .sort((a, b) => b[1] - a[1])
            .slice(0, 10);
        
        stats.topErrorGroups = sorted.map(([jid, count]) => ({
            jid,
            errorCount: count,
            lastError: this.lastErrors.get(jid)
        }));
        
        return stats;
    }
}

/**
 * Retry manager com circuit breaker
 */
export class RetryManager {
    constructor(logger, config = {}) {
        this.logger = logger;
        this.config = {
            maxRetries: config.maxRetries || 3,
            initialDelay: config.initialDelay || 1000,
            maxDelay: config.maxDelay || 30000,
            circuitBreakerThreshold: config.circuitBreakerThreshold || 5,
            circuitBreakerTimeout: config.circuitBreakerTimeout || 60000,
            ...config
        };
        
        this.circuitBreakers = new Map(); // groupJid -> { failures, lastFailure, state }
    }
    
    /**
     * Executa operação com retry
     * 
     * @param {Function} operation - Operação para executar
     * @param {string} groupJid - JID do grupo
     * @param {object} context - Contexto adicional
     * @returns {Promise<any>} Resultado da operação
     */
    async executeWithRetry(operation, groupJid, context = {}) {
        // Verifica circuit breaker
        if (this.isCircuitOpen(groupJid)) {
            throw new Error(`Circuit breaker open for ${groupJid}`);
        }
        
        let lastError;
        
        for (let attempt = 0; attempt < this.config.maxRetries; attempt++) {
            try {
                const result = await operation();
                
                // Sucesso - reseta circuit breaker
                this.recordSuccess(groupJid);
                
                return result;
            } catch (error) {
                lastError = error;
                
                this.logger.warn({
                    attempt: attempt + 1,
                    maxRetries: this.config.maxRetries,
                    error: error.message,
                    groupJid,
                    context
                }, 'operation failed, retrying');
                
                // Última tentativa - não espera
                if (attempt === this.config.maxRetries - 1) {
                    break;
                }
                
                // Calcula delay com backoff exponencial
                const delay = Math.min(
                    this.config.initialDelay * Math.pow(2, attempt),
                    this.config.maxDelay
                );
                
                // Adiciona jitter
                const jitter = delay * (0.8 + Math.random() * 0.4);
                
                await new Promise(resolve => setTimeout(resolve, jitter));
            }
        }
        
        // Todas as tentativas falharam
        this.recordFailure(groupJid);
        throw lastError;
    }
    
    /**
     * Verifica se circuit breaker está aberto
     * 
     * @param {string} groupJid - JID do grupo
     * @returns {boolean} Se está aberto
     */
    isCircuitOpen(groupJid) {
        const breaker = this.circuitBreakers.get(groupJid);
        
        if (!breaker || breaker.state !== 'OPEN') {
            return false;
        }
        
        // Verifica se timeout expirou (half-open)
        if (Date.now() - breaker.lastFailure > this.config.circuitBreakerTimeout) {
            breaker.state = 'HALF_OPEN';
            this.logger.info({ groupJid }, 'circuit breaker half-open');
            return false;
        }
        
        return true;
    }
    
    /**
     * Registra sucesso
     * 
     * @param {string} groupJid - JID do grupo
     */
    recordSuccess(groupJid) {
        const breaker = this.circuitBreakers.get(groupJid);
        
        if (breaker) {
            if (breaker.state === 'HALF_OPEN') {
                this.logger.info({ groupJid }, 'circuit breaker closed');
            }
            this.circuitBreakers.delete(groupJid);
        }
    }
    
    /**
     * Registra falha
     * 
     * @param {string} groupJid - JID do grupo
     */
    recordFailure(groupJid) {
        const breaker = this.circuitBreakers.get(groupJid) || {
            failures: 0,
            lastFailure: 0,
            state: 'CLOSED'
        };
        
        breaker.failures++;
        breaker.lastFailure = Date.now();
        
        if (breaker.failures >= this.config.circuitBreakerThreshold) {
            breaker.state = 'OPEN';
            this.logger.warn({
                groupJid,
                failures: breaker.failures
            }, 'circuit breaker opened');
        }
        
        this.circuitBreakers.set(groupJid, breaker);
    }
}

/**
 * Factory para criar validadores e handlers
 */
export function createGroupValidation(logger) {
    return {
        validator: new GroupValidator(logger),
        errorHandler: new GroupErrorHandler(logger),
        retryManager: new RetryManager(logger)
    };
}

export default {
    GroupValidator,
    GroupErrorHandler,
    RetryManager,
    createGroupValidation
};
